GROUP BY ?section
ORDER BY DESC(?count)
LIMIT 20

PREFIX npm: <https://purl.org/packagegraph/ontology/npm#>
PREFIX pkg: <https://purl.org/packagegraph/ontology/core#>

SELECT (AVG(?depth) AS ?avgDepth)
WHERE {
  ?package a npm:NpmPackage .
  {
    SELECT ?package (COUNT(?dep) AS ?depth)
    WHERE {
      ?package pkg:directlyDependsOn+ ?dep .
    }
    GROUP BY ?package
  }
}

PREFIX sec: <https://purl.org/packagegraph/ontology/security#>
PREFIX pkg: <https://purl.org/packagegraph/ontology/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?cveId ?osvId ?severity
WHERE {
  ?vuln sec:hasAffectedRange ?range .
  ?range sec:affectsPackageName "org.springframework:spring-beans" ;
         sec:affectsEcosystem/rdfs:label "Maven" .
  ?vuln sec:cveId ?cveId .
  OPTIONAL { ?vuln sec:osvId ?osvId }
  OPTIONAL { ?vuln sec:hasCVSSScore/sec:baseScore ?severity }
}
ORDER BY DESC(?severity)

PREFIX sec: <https://purl.org/packagegraph/ontology/security#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?introducedVersion ?fixedVersion
WHERE {
  ?vuln sec:cveId "CVE-2022-22965" ;
        sec:hasAffectedRange ?range .
  ?range sec:affectsPackageName "org.springframework:spring-beans" ;
         sec:affectsEcosystem/rdfs:label "Maven" ;
         sec:rangeType ?rangeTypeUri ;
         sec:hasRangeEvent ?event .
  FILTER(?rangeTypeUri IN (sec:range-ecosystem, sec:range-semver))
  OPTIONAL {
    ?event sec:eventType sec:event-introduced ;
           sec:eventVersion ?introducedVersion .
  }
  OPTIONAL {
    ?event sec:eventType sec:event-fixed ;
           sec:eventVersion ?fixedVersion .
  }
}

PREFIX sec: <https://purl.org/packagegraph/ontology/security#>
PREFIX vcs: <https://purl.org/packagegraph/ontology/vcs#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?fixedVersion ?commitHash ?commitUrl
WHERE {
  ?vuln sec:cveId "CVE-2022-22965" ;
        sec:hasAffectedRange ?range .
  ?range sec:affectsPackageName "org.springframework:spring-beans" ;
         sec:affectsEcosystem/rdfs:label "Maven" ;
         sec:hasRangeEvent ?event .
  ?event sec:eventType sec:event-fixed .

  OPTIONAL { ?event sec:eventVersion ?fixedVersion }
  OPTIONAL {
    ?event sec:eventCommit ?commit .
    ?commit vcs:commitHash ?commitHash .
    OPTIONAL {
      ?commit ^vcs:hasCommit ?repo .
      ?repo vcs:cloneUrl ?commitUrl .
    }
  }
}

PREFIX pkg: <https://purl.org/packagegraph/ontology/core#>
PREFIX vcs: <https://purl.org/packagegraph/ontology/vcs#>
PREFIX maven: <https://purl.org/packagegraph/ontology/maven#>

SELECT ?cloneUrl ?tag
WHERE {
  ?artifact maven:groupId "org.springframework" ;
            maven:artifactId "spring-core" ;
            pkg:hasVersion/pkg:versionString "6.2.0" ;
            pkg:isVersionOf ?identity .

  OPTIONAL { ?identity pkg:upstreamRepository ?repo .
             ?repo vcs:cloneUrl ?cloneUrl }
  OPTIONAL { ?artifact vcs:packagedFromTag/vcs:tagName ?tag }
}

PREFIX pkg: <https://purl.org/packagegraph/ontology/core#>
PREFIX vcs: <https://purl.org/packagegraph/ontology/vcs#>
PREFIX maven: <https://purl.org/packagegraph/ontology/maven#>

SELECT ?currentVersion ?previousVersion ?diffUrl
       ?linesAdded ?linesDeleted ?filesChanged
WHERE {
  ?artifact maven:groupId "org.springframework" ;
            maven:artifactId "spring-core" ;
            pkg:hasVersion/pkg:versionString ?currentVersion ;
            pkg:isVersionOf ?identity .
  ?identity pkg:upstreamRepository ?repo .

  ?release vcs:correspondingPackageVersion/pkg:versionString ?currentVersion ;
           vcs:hasDiff ?diff ;
           vcs:previousRelease ?prevRelease .
  ?prevRelease vcs:correspondingPackageVersion/pkg:versionString ?previousVersion .

  ?diff vcs:diffUrl ?diffUrl .
  OPTIONAL { ?diff vcs:linesAdded ?linesAdded }
  OPTIONAL { ?diff vcs:linesDeleted ?linesDeleted }
  OPTIONAL { ?diff vcs:filesChanged ?filesChanged }
}

PREFIX pkg: <https://purl.org/packagegraph/ontology/core#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?fedoraName ?pypiName ?confidence ?method
WHERE {
  ?fedoraId a pkg:PackageIdentity ;
            pkg:identityName ?fedoraName ;
            pkg:hasPackageRelationship ?rel .
  ?rel pkg:relationshipTarget ?pypiId ;
       pkg:matchMethod ?methodConcept ;
       pkg:matchConfidence ?confidence .
  ?methodConcept skos:prefLabel ?method .
  ?pypiId pkg:identityName ?pypiName .

  ?fedoraPkg pkg:isVersionOf ?fedoraId ;
             pkg:partOfRelease/^pkg:hasRelease/rdfs:label "Fedora" .

  FILTER(?confidence > "0.9"^^xsd:decimal)
}
ORDER BY DESC(?confidence)

PREFIX pkg: <https://purl.org/packagegraph/ontology/core#>
PREFIX sec: <https://purl.org/packagegraph/ontology/security#>
PREFIX tax: <https://purl.org/packagegraph/ontology/taxonomy#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?projectName ?cveId ?cvssScore
WHERE {
  ?upstream a pkg:UpstreamProject ;
            pkg:projectName ?projectName ;
            pkg:hasClassification tax:role-framework ;
            pkg:hasClassification tax:domain-web-development .
  ?identity pkg:hasUpstreamProject ?upstream .
  ?vuln sec:affectsPackage ?identity ;
        sec:cveId ?cveId .
  OPTIONAL { ?vuln sec:hasCVSSScore/sec:baseScore ?cvssScore }
  FILTER NOT EXISTS {
    ?advisory sec:addressesVulnerability ?vuln .
  }
}
ORDER BY DESC(?cvssScore)

PREFIX pkg: <https://purl.org/packagegraph/ontology/core#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX tax: <https://purl.org/packagegraph/ontology/taxonomy#>

SELECT ?facetLabel ?termLabel (COUNT(DISTINCT ?subject) AS ?count)
WHERE {
  ?subject pkg:hasClassification ?term .
  ?term skos:inScheme tax:TaxonomyScheme ;
        skos:prefLabel ?termLabel .
  ?facet skos:member ?term ;
         skos:prefLabel ?facetLabel .
}
GROUP BY ?facetLabel ?termLabel
ORDER BY ?facetLabel DESC(?count)

PREFIX sec: <https://purl.org/packagegraph/ontology/security#>
PREFIX pkg: <https://purl.org/packagegraph/ontology/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cveId ?packageName ?epssScore ?cvssScore
WHERE {
  ?vuln sec:cveId ?cveId ;
        sec:affectsPackage ?identity ;
        sec:hasEPSSAssessment ?epss ;
        sec:hasCVSSScore ?cvss .
  ?epss sec:epssScore ?epssScore ;
        sec:epssAssessmentDate ?epssDate .
  ?cvss sec:baseScore ?cvssScore .
  ?identity pkg:identityName ?packageName .

  ?package pkg:isVersionOf ?identity ;
           pkg:partOfRelease ?release .
  ?release ^pkg:hasRelease/rdfs:label "Fedora" ;
           pkg:releaseVersion "43" .

  FILTER(?epssScore > "0.5"^^xsd:decimal)

  # Most recent EPSS assessment
  FILTER NOT EXISTS {
    ?vuln sec:hasEPSSAssessment ?newerEpss .
    ?newerEpss sec:epssAssessmentDate ?newerDate .
    FILTER(?newerDate > ?epssDate)
  }

  # Not patched
  FILTER NOT EXISTS {
    ?advisory sec:addressesVulnerability ?vuln ;
              sec:advisoryForPackage ?package .
  }
}
ORDER BY DESC(?epssScore)

PREFIX sec: <https://purl.org/packagegraph/ontology/security#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cveId ?epssScore ?cvssScore
WHERE {
  ?vuln sec:cveId ?cveId ;
        sec:hasEPSSAssessment ?epss ;
        sec:hasCVSSScore ?cvss .
  ?epss sec:epssScore ?epssScore .
  ?cvss sec:cvssVersion "3.1" ;
        sec:baseScore ?cvssScore .
  FILTER(
    (?epssScore > "0.7"^^xsd:decimal && ?cvssScore < "4.0"^^xsd:decimal) ||
    (?epssScore < "0.1"^^xsd:decimal && ?cvssScore > "9.0"^^xsd:decimal)
  )
}
ORDER BY DESC(?epssScore)
